<script setup lang="ts">
import { computed,ref } from 'vue'
import { Box,Button,Footer,Header,Heading,Modal,ModalBody,Table,TableBody,TableCell,TableHead,TableHeader,TableRow,Text } from '../ui'
import IconButton from '../ui/IconButton.vue'
import type { ChartPreparation } from '../../core/chartDatasetContract'
import { preparedChartDataset } from '../../core/chartDataset'
import { pivotChartData } from '../../core/chartPivot'
import { useEditor } from '../../composables/useEditor'
const props=withDefaults(defineProps<{preparation:ChartPreparation;readOnly?:boolean;disabled?:boolean;replaceAttachment?:boolean}>(),{readOnly:false,disabled:false,replaceAttachment:false})
const emit=defineEmits<{adopt:[]}>(),editor=useEditor(),open=ref(false),error=ref(''),sourcePage=ref(0),widePage=ref(0),pageSize=20
const state=computed(()=>{try{return{value:pivotChartData(props.preparation),error:''}}catch(e){return{value:null,error:e instanceof Error&&'issues'in e?(e.issues as {message:string}[]).slice(0,2).map(issue=>issue.message).join('；'):(e as Error).message}}})
const sourcePages=computed(()=>Math.ceil(props.preparation.source.rows.length/pageSize)),widePages=computed(()=>Math.ceil((state.value.value?.rows.length??0)/pageSize))
function adopt(){
  if(props.disabled)return
  try{
    const data=preparedChartDataset(props.preparation),current=editor.assistantDataset.value
    if(!props.replaceAttachment&&current&&JSON.stringify(current)!==JSON.stringify(props.preparation.source)&&JSON.stringify(current)!==JSON.stringify(data))throw new Error('当前数据附件已改变，请先移除当前附件，再采用这份已核对的整理结果')
    editor.assistantDataset.value=data;editor.notice.value='已采用整理后的附件，原始长表保留；请继续发送绘图目标'
    open.value=false;error.value='';emit('adopt')
  }catch(e){error.value=(e as Error).message}
}
</script>
<template>
  <Box class="chart-preparation" aria-label="长表整理方案"><Text v-if="state.value">原表 {{ preparation.source.rows.length }} 行 → {{ state.value.rows.length }} 行 × {{ state.value.groups.length }} 个数值组{{ preparation.operation.errorColumn?'（含配对误差）':'' }}；不聚合、不补值。</Text><Button size="xs" :disabled="disabled||!state.value" @click="sourcePage=0;widePage=0;open=true;error=''">{{ readOnly?'查看原始长表与整理映射':'预览长表整理' }}</Button><Text v-if="state.error" role="alert" class="error-text">{{ state.error }}</Text></Box>
  <Modal :open="open" size="xl" label="长表整理预览" class="chart-preparation-dialog" @close="open=false"><Header><Box><Heading>{{ readOnly?'原始长表与整理记录':'核对长表转宽表' }}</Heading><Text class="muted-caption">{{ preparation.source.name }} · {{ preparation.source.origin==='example'?'示例数据':'用户填写的数据' }} · {{ preparation.source.sampleMeaning==='raw-observations'?'使用者声明为原始观测':preparation.source.sampleMeaning==='summaries'?'已汇总统计量':'数值含义未确认' }}</Text></Box><IconButton icon="close" label="关闭长表整理预览" @click="open=false" /></Header><ModalBody><template v-if="state.value"><Box class="chart-preparation-rules"><Text>行标识：{{ state.value.mapping.row }} · 展开组别：{{ state.value.mapping.group }} · 数值：{{ state.value.mapping.value }}<Text v-if="state.value.mapping.error"> · 误差半宽：{{ state.value.mapping.error }} · {{ preparation.source.errorLabel }}</Text></Text><Text>保留 {{ state.value.providedCells }} 条源记录；输入空值 {{ state.value.blankValues }} 个<Text v-if="preparation.operation.errorColumn">，误差空值 {{ state.value.blankErrors }} 个</Text>，未提供的组合 {{ state.value.absentCells }} 个。空值不补零，零保持为零。</Text><Text>行与组按首次出现顺序排列；完整复合“行标识＋组别”重复会报错，不平均、求和或覆盖。</Text><Text v-if="preparation.operation.rowColumns.length>1||preparation.operation.groupColumns.length>1" class="muted-caption">复合标签用“ · ”连接；字段内部的分隔符会转义，原始字段完整保留。</Text><Text v-if="state.value.unusedColumns.length" class="placement-message">未参与展开的列：{{ state.value.unusedColumns.join('、') }}。完整原表仍保留，请核对是否遗漏分组条件或其他指标。</Text></Box><Box class="chart-preparation-grid"><Box><Heading>原始长表</Heading><Box class="chart-data-table-scroll"><Table aria-label="整理前原始长表"><TableHead><TableRow><TableHeader>源行</TableHeader><TableHeader v-for="column in preparation.source.columns" :key="column">{{ column }}</TableHeader></TableRow></TableHead><TableBody><TableRow v-for="(row,i) in preparation.source.rows.slice(sourcePage*pageSize,(sourcePage+1)*pageSize)" :key="i"><TableCell>{{ sourcePage*pageSize+i+2 }}</TableCell><TableCell v-for="(cell,j) in row" :key="j">{{ cell===''?'（输入空值）':cell }}</TableCell></TableRow></TableBody></Table></Box><Box class="material-actions"><Button size="xs" :disabled="sourcePage===0" @click="sourcePage--">原表上一页</Button><Text>{{ sourcePage+1 }} / {{ sourcePages }} 页</Text><Button size="xs" :disabled="sourcePage+1>=sourcePages" @click="sourcePage++">原表下一页</Button></Box></Box><Box><Heading>整理后宽表</Heading><Box class="chart-data-table-scroll"><Table aria-label="整理后宽表"><TableHead><TableRow><TableHeader v-for="column in state.value.columns" :key="column">{{ column }}</TableHeader></TableRow></TableHead><TableBody><TableRow v-for="(row,i) in state.value.rows.slice(widePage*pageSize,(widePage+1)*pageSize)" :key="i"><TableCell v-for="(cell,j) in row" :key="j" :title="j?state.value.sourceRows[widePage*pageSize+i]![j-1]===null?'原表未提供该组合':`源表第 ${state.value.sourceRows[widePage*pageSize+i]![j-1]!+2} 行 · ${preparation.source.columns[state.value.sourceColumns[j-1]!]}`:undefined">{{ j&&cell===''?(state.value.sourceRows[widePage*pageSize+i]![j-1]===null?'（未提供）':'（输入空值）'):cell }}</TableCell></TableRow></TableBody></Table></Box><Box class="material-actions"><Button size="xs" :disabled="widePage===0" @click="widePage--">宽表上一页</Button><Text>{{ widePage+1 }} / {{ widePages }} 页</Text><Button size="xs" :disabled="widePage+1>=widePages" @click="widePage++">宽表下一页</Button></Box><Text class="muted-caption">数值与误差单元格可悬停查看源表行号和列名。采用后仍需选择图型；未参与展开的列不会作为当前宽表绘制。</Text></Box></Box></template><Text v-if="error||state.error" role="alert" class="error-text">{{ error||state.error }}</Text></ModalBody><Footer><Text class="muted-caption">{{ readOnly?'原始值和映射随图表保存。':'本操作只替换助手的数据附件，当前画布保持。不会自动调用模型。' }}</Text><Box class="header-spacer" /><Button @click="open=false">{{ readOnly?'关闭':'保留当前附件' }}</Button><Button v-if="!readOnly" variant="primary" :disabled="disabled||!state.value" @click="adopt">采用为数据附件</Button></Footer></Modal>
</template>
